namespace Sphene.UI.Components;

/// <summary>
/// Provides official brand logos as embedded white-silhouette textures
/// (alpha channel carries the glyph) so they can be tinted to any color,
/// plus ready-made brand-colored buttons. PNGs are generated by
/// <c>tools/generate_brand_icons.sh</c> · regenerate that file to add brands.
/// </summary>
public static partial class SpheneBrandIcons
{
    /// <summary>Brand icon identifier.</summary>
    public enum Brand
    {
        Discord,
        Kofi,
        Bluesky,
        Carrd,
        GitHub,
        Instagram,
        Patreon,
        TikTok,
        Twitch,
        X,
        YouTube,
        Sphene
    }

    /// <summary>Discord blurple brand color.</summary>
    public static readonly Vector4 DiscordColor = new(0.345f, 0.396f, 0.949f, 1f);
    /// <summary>Ko-fi coral brand color.</summary>
    public static readonly Vector4 KofiColor = new(1.0f, 0.392f, 0.2f, 1f);
    /// <summary>Slightly brightened variants for hover/active states.</summary>
    public static readonly Vector4 DiscordColorHover = new(0.42f, 0.47f, 1f, 1f);
    public static readonly Vector4 KofiColorHover = new(1f, 0.52f, 0.32f, 1f);

    private static readonly Dictionary<Brand, string> BrandPngs = new()
    {
        [Brand.Discord] = DiscordPngBase64,
        [Brand.Kofi] = KofiPngBase64,
        [Brand.Bluesky] = BlueskyPngBase64,
        [Brand.Carrd] = CarrdPngBase64,
        [Brand.GitHub] = GitHubPngBase64,
        [Brand.Instagram] = InstagramPngBase64,
        [Brand.Patreon] = PatreonPngBase64,
        [Brand.TikTok] = TikTokPngBase64,
        [Brand.Twitch] = TwitchPngBase64,
        [Brand.X] = XPngBase64,
        [Brand.YouTube] = YouTubePngBase64,
    };

    /// <summary>Returns the embedded texture for <paramref name="brand"/>, loading it lazily.</summary>
    public static IDalamudTextureWrap? GetTexture(Brand brand)
    {
        if (brand == Brand.Sphene)
        {
            return SpheneLogo();
        }
        if (!BrandPngs.TryGetValue(brand, out var png))
        {
            return null;
        }
        return SpheneUI.Media.Texture($"brand:{brand.ToString().ToLowerInvariant()}",
            () => Convert.FromBase64String(png));
    }

    /// <summary>
    /// The Sphene plugin logo from the embedded <c>images/icon.png</c>
    /// resource · colored artwork, do not tint. Returns null while decoding.
    /// </summary>
    public static IDalamudTextureWrap? SpheneLogo()
        => SpheneUI.Media.Texture("brand:sphene-logo", LoadSpheneLogoBytes);

    private static byte[]? LoadSpheneLogoBytes()
    {
        var assembly = typeof(SpheneBrandIcons).Assembly;
        var resourceName = assembly.GetManifestResourceNames()
            .FirstOrDefault(n => n.EndsWith("images.icon.png", StringComparison.OrdinalIgnoreCase));
        if (resourceName == null)
        {
            return null;
        }
        using var stream = assembly.GetManifestResourceStream(resourceName);
        if (stream == null)
        {
            return null;
        }
        using var memory = new MemoryStream();
        stream.CopyTo(memory);
        return memory.ToArray();
    }

    private static readonly Dictionary<Brand, Vector4> BrandColors = new()
    {
        [Brand.Discord] = DiscordColor,
        [Brand.Kofi] = KofiColor,
        [Brand.Bluesky] = new(0.03f, 0.55f, 1f, 1f),
        // deep slate - matches the logo's dark base, keeps white text crisp
        [Brand.Sphene] = new Vector4(0.16f, 0.14f, 0.24f, 1f),
        [Brand.Carrd] = new(0.58f, 0.45f, 0.98f, 1f),
        [Brand.GitHub] = new(0.91f, 0.93f, 0.95f, 1f),
        [Brand.Instagram] = new(0.88f, 0.19f, 0.42f, 1f),
        [Brand.Patreon] = new(1f, 0.26f, 0.30f, 1f),
        [Brand.TikTok] = new(0.0f, 0.95f, 0.92f, 1f),
        [Brand.Twitch] = new(0.57f, 0.27f, 1f, 1f),
        [Brand.X] = new(0.93f, 0.93f, 0.95f, 1f),
        [Brand.YouTube] = new(1f, 0f, 0.2f, 1f),
    };

    /// <summary>Returns the brand color for <paramref name="brand"/>  · 
    /// dark marks like X/GitHub return a light tone so they read on the
    /// dark theme.</summary>
    public static Vector4 GetBrandColor(Brand brand)
        => BrandColors.TryGetValue(brand, out var c) ? c : DiscordColor;

    /// <summary>Returns the hover brand color for <paramref name="brand"/>.</summary>
    public static Vector4 GetBrandHoverColor(Brand brand)
    {
        var c = GetBrandColor(brand);
        return new Vector4(MathF.Min(1f, c.X * 1.15f), MathF.Min(1f, c.Y * 1.15f),
            MathF.Min(1f, c.Z * 1.15f), c.W);
    }

    /// <summary>Draws a tinted brand glyph into <paramref name="drawList"/> inside the given rect.</summary>
    public static void DrawIcon(ImDrawListPtr drawList, Brand brand,
        Vector2 min, Vector2 max, Vector4? tint = null)
    {
        var texture = GetTexture(brand);
        if (texture == null)
            return;
        var color = tint ?? GetBrandColor(brand);
        SpheneUI.Media.ImageInRect(drawList, texture, min, max, ImageFit.Stretch, color);
    }

    /// <summary>Draws a centered tinted brand glyph button of the given square size.</summary>
    /// <returns>True when the button was clicked.</returns>
    public static bool IconButton(Brand brand, string id,
        float size, Vector4? tint = null, string? tooltip = null)
    {
        ImGui.PushID(id);
        var pos = ImGui.GetCursorScreenPos();
        var result = ImGui.InvisibleButton($"##brandBtn{id}", new Vector2(size, size));
        var hovered = ImGui.IsItemHovered();
        var color = tint ?? (hovered ? GetBrandHoverColor(brand) : GetBrandColor(brand));
        var inset = size * 0.15f;
        DrawIcon(ImGui.GetWindowDrawList(), brand,
            pos + new Vector2(inset, inset), pos + new Vector2(size - inset, size - inset), color);
        if (tooltip != null && hovered)
            SpheneUI.AttachTooltip(tooltip);
        ImGui.PopID();
        return result;
    }

    /// <summary>One button split down the middle: left half Ko-fi, right half
    /// perks - breathing pulse, per-half hover, shared by the setup and the
    /// supporter page so the two can never drift.</summary>
    /// <returns>(kofi hit, perks hit) for the caller to act on.</returns>
    public static (bool kofi, bool perks) KofiPerksSplit(float width, float height)
    {
        var scale = SpheneUI.Scale;
        var drawList = ImGui.GetWindowDrawList();
        var min = ImGui.GetCursorScreenPos();
        var max = min + new Vector2(width, height);
        var radius = MathF.Min(SpheneUI.Metrics.ButtonRadius, height * 0.3f);
        var kofiAccent = GetBrandColor(Brand.Kofi);
        var gold = SpheneUI.Palette.SpheneGold;
        var half = new Vector2(width * 0.5f, height);

        ImGui.PushID("kofiperks");
        ImGui.SetCursorScreenPos(min);
        var kofiHit = ImGui.InvisibleButton("##lefthalf", half);
        var kofiHov = ImGui.IsItemHovered();
        ImGui.SetCursorScreenPos(new Vector2(min.X + half.X, min.Y));
        var perksHit = ImGui.InvisibleButton("##righthalf", half);
        var perksHov = ImGui.IsItemHovered();
        ImGui.PopID();
        ImGui.SetCursorScreenPos(new Vector2(min.X, max.Y));

        var t = (float)(ImGui.GetTime() % 2.0);
        var pulse = 0.5f + 0.5f * MathF.Sin(t * MathF.PI * 2f);
        var midX = min.X + half.X;

        // two tinted halves - each breathes and brightens on its own hover
        var leftCol = SpheneUI.ColorUtils.LerpColor(kofiAccent, Vector4.One,
            (kofiHov ? 0.30f : 0f) + pulse * 0.10f);
        var rightCol = SpheneUI.ColorUtils.LerpColor(gold, Vector4.One,
            (perksHov ? 0.30f : 0f) + pulse * 0.10f);
        drawList.AddRectFilled(min, new Vector2(midX, max.Y),
            SpheneUI.ColorUtils.ToU32(SpheneUI.ColorUtils.WithAlpha(leftCol, 0.95f)),
            radius, ImDrawFlags.RoundCornersLeft);
        drawList.AddRectFilled(new Vector2(midX, min.Y), max,
            SpheneUI.ColorUtils.ToU32(SpheneUI.ColorUtils.WithAlpha(rightCol, 0.95f)),
            radius, ImDrawFlags.RoundCornersRight);

        drawList.AddRect(min, max, SpheneUI.ColorUtils.ToU32(SpheneUI.ColorUtils.WithAlpha(
            SpheneUI.ColorUtils.LerpColor(gold, Vector4.One, pulse * 0.5f),
            0.55f + 0.45f * pulse)), radius, ImDrawFlags.RoundCornersAll,
            MathF.Max(1.5f, 1.5f * scale));

        drawList.AddLine(new Vector2(midX, min.Y + 7f * scale),
            new Vector2(midX, max.Y - 7f * scale),
            SpheneUI.ColorUtils.ToU32(new Vector4(1f, 1f, 1f, 0.30f)));

        // left half: kofi glyph + label · right half: gift glyph + label -
        // the gold side needs dark content to stay readable
        var iconS = height * 0.45f;
        void DrawHalf(Vector2 halfMin, Brand? brand,
            FontAwesomeIcon? glyph, string label, Vector4 contentCol)
        {
            var contentU32 = SpheneUI.ColorUtils.ToU32(contentCol);
            var labelW = ImGui.CalcTextSize(label).X;
            var groupW = iconS + 6f * scale + labelW;
            var x = halfMin.X + (half.X - groupW) * 0.5f;
            var iconMin = new Vector2(x, halfMin.Y + (height - iconS) * 0.5f);
            if (brand.HasValue)
            {
                DrawIcon(drawList, brand.Value, iconMin,
                    iconMin + new Vector2(iconS), contentCol);
            }
            else if (glyph.HasValue)
            {
                using (SpheneUI.IconFont.Push())
                {
                    drawList.AddText(iconMin, contentU32, glyph.Value.ToIconString());
                }
            }
            var textPos = new Vector2(x + iconS + 6f * scale,
                halfMin.Y + (height - ImGui.GetTextLineHeight()) * 0.5f);
            drawList.AddText(textPos, contentU32, label);
        }
        DrawHalf(min, Brand.Kofi, null, "Ko-fi", Vector4.One);
        DrawHalf(new Vector2(midX, min.Y), null, FontAwesomeIcon.Gift, "perks",
            new Vector4(0.12f, 0.08f, 0.02f, 1f));

        SpheneUI.AttachTooltip("Ko-fi: support Sphene · perks: see what it unlocks");
        return (kofiHit, perksHit);
    }

    /// <summary>Computes the width of a brand icon + text button.</summary>
    public static float GetIconTextButtonSize(string text)
    {
        var scale = ImGuiHelpers.GlobalScale;
        return ImGui.GetFrameHeight() + 10f * scale
            + ImGui.CalcTextSize(text).X + 12f * scale;
    }

    /// <summary>
    /// Brand-colored segmented button: the brand glyph sits in the icon zone
    /// (solid brand fill) next to the label · the shared button language
    /// tinted with the brand color.
    /// </summary>
    /// <returns>True when the button was clicked.</returns>
    public static bool IconTextButton(Brand brand, string text,
        string id, float? width = null, string? tooltip = null, float? height = null)
    {
        ImGui.PushID(id);
        var buttonHeight = height ?? ImGui.GetFrameHeight();
        var iconSize = MathF.Min(buttonHeight * 0.58f, ImGui.GetTextLineHeight() * 1.5f);
        var buttonWidth = width ?? GetIconTextButtonSize(text);
        var accent = GetBrandColor(brand);
        var glyphInset = (buttonHeight - iconSize) * 0.5f;

        var result = SpheneUI.Controls.SegCore($"##brandTextBtn{id}", text, null,
            new Vector2(buttonWidth, buttonHeight), accent, solidFill: true,
            labelColor: Vector4.One,
            zoneContent: (dl, zn, zx) => DrawIcon(dl, brand,
                zn + new Vector2(glyphInset), zx - new Vector2(glyphInset),
                Vector4.One));

        if (tooltip != null && ImGui.IsItemHovered())
            SpheneUI.AttachTooltip(tooltip);
        ImGui.PopID();
        return result;
    }
    /// <summary>
    /// Draws a square button with the brand color as its background and the
    /// brand glyph in white. The background brightens on hover.
    /// </summary>
    /// <returns>True when the button was clicked.</returns>
    public static bool FramedIconButton(Brand brand, string id,
        float size, string? tooltip = null)
    {
        ImGui.PushID(id);
        var pos = ImGui.GetCursorScreenPos();
        ImGui.PushStyleColor(ImGuiCol.Button, GetBrandColor(brand));
        ImGui.PushStyleColor(ImGuiCol.ButtonHovered, GetBrandHoverColor(brand));
        ImGui.PushStyleColor(ImGuiCol.ButtonActive, GetBrandHoverColor(brand));
        var result = SpheneUI.Controls.Button($"##brandFrameBtn{id}", new Vector2(size, size));
        ImGui.PopStyleColor(3);
        var inset = size * 0.11f;
        DrawIcon(ImGui.GetWindowDrawList(), brand,
            pos + new Vector2(inset, inset), pos + new Vector2(size - inset, size - inset), Vector4.One);
        if (tooltip != null && ImGui.IsItemHovered())
            SpheneUI.AttachTooltip(tooltip);
        ImGui.PopID();
        return result;
    }

    /// <summary>One clickable segment of a <see cref="BrandStrip"/>.</summary>
    public readonly record struct StripSegment(
        Brand Brand, string? Label = null, string? Tooltip = null, Action? OnClick = null);

    /// <summary>
    /// Draws a joined brand button strip at the cursor: contiguous segments blend
    /// their brand colors at the seams and the whole strip fades to real
    /// transparency on every edge (alpha gradient like the scroll fade).
    /// Segments may carry a white text label next to the white glyph.
    /// </summary>
    /// <param name="width">Total strip width; null auto-sizes each segment to its content.</param>
    /// <returns>The strip size so callers can align following content.</returns>
    public static Vector2 BrandStrip(string id,
        IReadOnlyList<StripSegment> segments, float height, float? width = null)
    {
        var count = segments.Count;
        var scale = ImGuiHelpers.GlobalScale;
        var widths = new float[count];
        var autoTotal = 0f;
        for (var k = 0; k < count; k++)
        {
            widths[k] = SegmentWidth(segments[k], height, scale);
            autoTotal += widths[k];
        }

        var totalWidth = width ?? autoTotal;
        if (autoTotal > 0f)
        {
            var factor = totalWidth / autoTotal;
            for (var k = 0; k < count; k++)
                widths[k] *= factor;
        }

        var pos = ImGui.GetCursorScreenPos();
        var colors = new Vector4[count];
        var x = pos.X;
        for (var k = 0; k < count; k++)
        {
            ImGui.SetCursorScreenPos(new Vector2(x, pos.Y));
            var clicked = ImGui.InvisibleButton($"##brandStrip{id}{k}", new Vector2(widths[k], height));
            var hovered = ImGui.IsItemHovered();
            colors[k] = hovered ? GetBrandHoverColor(segments[k].Brand)
                : GetBrandColor(segments[k].Brand);
            if (clicked)
            {
                segments[k].OnClick?.Invoke();
            }
            if (!string.IsNullOrEmpty(segments[k].Tooltip) && hovered)
            {
                SpheneUI.AttachTooltip(segments[k].Tooltip!);
            }
            x += widths[k];
        }
        ImGui.SetCursorScreenPos(pos + new Vector2(totalWidth, height));

        DrawStripSurface(ImGui.GetWindowDrawList(), pos, widths, colors, segments, height);
        return new Vector2(totalWidth, height);
    }

    /// <summary>Natural width of one strip segment (icon-only or icon + label).</summary>
    private static float SegmentWidth(StripSegment segment, float height, float scale)
    {
        var iconSize = height * 0.55f;
        if (segment.Label == null)
            return height * 1.15f;
        var pad = height * 0.5f;
        return pad * 2f + iconSize + 5f * scale + ImGui.CalcTextSize(segment.Label).X;
    }

    /// <summary>
    /// Renders the strip surface as a single grid sampled from a continuous
    /// gradient: segment colors blend at seams, every edge fades to alpha zero.
    /// </summary>
    private static void DrawStripSurface(ImDrawListPtr drawList,
        Vector2 pos, float[] widths, Vector4[] colors,
        IReadOnlyList<StripSegment> segments, float height)
    {
        const float edgeFadeFractionY = 0.32f;
        const float edgeFadeWidth = 10f;
        const float blendHalfWidth = 10f;
        const int fadeSteps = 3;
        var count = widths.Length;
        var totalWidth = 0f;
        var bounds = new float[count + 1];
        for (var k = 0; k < count; k++)
        {
            bounds[k] = totalWidth;
            totalWidth += widths[k];
        }
        bounds[count] = totalWidth;

        var stripMin = pos;
        var stripMax = pos + new Vector2(totalWidth, height);
        var fadeW = MathF.Min(edgeFadeWidth, totalWidth * 0.08f);
        var fadeH = height * edgeFadeFractionY;
        var blendHalf = MathF.Min(blendHalfWidth, totalWidth * 0.04f);

        // Subdivided stop lists: fade zones get several samples so the alpha
        // curve can bend (harder ramp) and corners interpolate round instead
        // of producing a diagonal cut.
        var xs = new List<float> { stripMin.X };
        for (var s = 1; s <= fadeSteps; s++)
            xs.Add(stripMin.X + fadeW * s / fadeSteps);
        for (var k = 1; k < count; k++)
        {
            xs.Add(stripMin.X + bounds[k] - blendHalf);
            xs.Add(stripMin.X + bounds[k] + blendHalf);
        }
        for (var s = fadeSteps - 1; s >= 0; s--)
            xs.Add(stripMax.X - fadeW * s / fadeSteps);
        xs.Sort();
        for (var i = xs.Count - 1; i > 0; i--)
            if (xs[i] - xs[i - 1] < 0.5f)
                xs.RemoveAt(i);

        var ys = new List<float> { stripMin.Y };
        for (var s = 1; s <= fadeSteps; s++)
            ys.Add(stripMin.Y + fadeH * s / fadeSteps);
        for (var s = fadeSteps; s >= 0; s--)
            ys.Add(stripMax.Y - fadeH * s / fadeSteps);

        for (var r = 0; r < ys.Count - 1; r++)
        {
            var rowMinY = ys[r];
            var rowMaxY = ys[r + 1];
            if (rowMaxY - rowMinY <= 0f)
                continue;
            var vT = StripVerticalAlpha(rowMinY, stripMin.Y, stripMax.Y, fadeH);
            var vB = StripVerticalAlpha(rowMaxY, stripMin.Y, stripMax.Y, fadeH);

            for (var c = 0; c < xs.Count - 1; c++)
            {
                var colMin = new Vector2(xs[c], rowMinY);
                var colMax = new Vector2(xs[c + 1], rowMaxY);
                if (colMax.X - colMin.X <= 0f)
                    continue;

                var cl = StripColorAt(colMin.X - stripMin.X, bounds, colors, blendHalf);
                var cr = StripColorAt(colMax.X - stripMin.X, bounds, colors, blendHalf);
                var aL = StripEdgeAlpha(colMin.X, stripMin.X, stripMax.X, fadeW);
                var aR = StripEdgeAlpha(colMax.X, stripMin.X, stripMax.X, fadeW);

                drawList.AddRectFilledMultiColor(colMin, colMax,
                    FadedColor(cl, aL * vT),
                    FadedColor(cr, aR * vT),
                    FadedColor(cr, aR * vB),
                    FadedColor(cl, aL * vB));
            }
        }

        // White glyphs and labels on top
        var scale = ImGuiHelpers.GlobalScale;
        var iconSize = height * 0.55f;
        var gap = 5f * scale;
        var textColor = ImGui.GetColorU32(ImGuiCol.Text);
        for (var k = 0; k < count; k++)
        {
            var segMin = pos + new Vector2(bounds[k], 0f);
            var segW = widths[k];
            var label = segments[k].Label;
            var contentW = label == null ? iconSize
                : iconSize + gap + ImGui.CalcTextSize(label).X;
            var contentX = segMin.X + (segW - contentW) * 0.5f;
            var iconMin = new Vector2(contentX, segMin.Y + (height - iconSize) * 0.5f);
            DrawIcon(drawList, segments[k].Brand,
                iconMin, iconMin + new Vector2(iconSize, iconSize), Vector4.One);
            if (label != null)
            {
                var textPos = new Vector2(contentX + iconSize + gap,
                    segMin.Y + (height - ImGui.GetTextLineHeight()) * 0.5f);
                drawList.AddText(textPos, textColor, label);
            }
        }
    }

    /// <summary>Continuous horizontal strip color: brand color per segment, lerped in seam zones.</summary>
    private static Vector4 StripColorAt(float localX, float[] bounds, Vector4[] colors, float blendHalf)
    {
        var count = colors.Length;
        var seg = count - 1;
        for (var k = 0; k < count; k++)
        {
            if (localX < bounds[k + 1])
            {
                seg = k;
                break;
            }
        }
        for (var k = 1; k < count; k++)
        {
            var seam = bounds[k];
            if (localX > seam - blendHalf && localX < seam + blendHalf)
            {
                var t = Math.Clamp((localX - seam + blendHalf) / (2f * blendHalf), 0f, 1f);
                return Vector4.Lerp(colors[k - 1], colors[k], t);
            }
        }
        return colors[seg];
    }

    /// <summary>Horizontal alpha ramp at the outer strip edges, curved for a harder fade.</summary>
    private static float StripEdgeAlpha(float x, float stripMinX, float stripMaxX, float fadeW)
    {
        if (fadeW <= 0f)
            return 1f;
        var t = x < stripMinX + fadeW ? (x - stripMinX) / fadeW
            : x > stripMaxX - fadeW ? (stripMaxX - x) / fadeW
            : 1f;
        return FadeCurve(t);
    }

    /// <summary>Vertical alpha ramp at the top/bottom strip edges, curved for a harder fade.</summary>
    private static float StripVerticalAlpha(float y, float stripMinY, float stripMaxY, float fadeH)
    {
        if (fadeH <= 0f)
            return 1f;
        var t = y < stripMinY + fadeH ? (y - stripMinY) / fadeH
            : y > stripMaxY - fadeH ? (stripMaxY - y) / fadeH
            : 1f;
        return FadeCurve(t);
    }

    /// <summary>Exponent &lt; 1 pushes opacity toward the edge so fades start hard and ease out.</summary>
    private static float FadeCurve(float t)
        => MathF.Pow(Math.Clamp(t, 0f, 1f), 0.6f);

    private static uint FadedColor(Vector4 color, float alphaFactor)
        => ImGui.ColorConvertFloat4ToU32(SpheneUI.ColorUtils.WithAlpha(color, color.W * alphaFactor));
}
